{
  "name": "@siming-org/opencode-plugin",
  "version": "0.1.22",
  "description": "opencode v2 plugin for siming: registers MCP task tools (siming_*), onboarding guide skill, siming_cli/siming_refresh tools, and global+project skills/subagents pulled live from the siming server",
  "type": "module",
  "keywords": [
    "opencode-plugin"
  ],
  "exports": {
    "./server": "./dist/server/index.js"
  },
  "files": [
    "dist"
  ],
  "dependencies": {
    "jsonc-parser": "^3.3.1",
    "zod": "^4.4.3",
    "@siming-org/cli": "0.8.22"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.18.35",
    "@types/node": "^26.0.0",
    "@typescript/native-preview": "^7.0.0-dev.20260518.1",
    "tsx": "^4.20.0",
    "typescript": "^5.8.0",
    "vitest": "^2.1.9"
  },
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "typecheck": "tsgo --noEmit",
    "test": "vitest run",
    "clean": "rm -rf dist"
  }
}

/**
 * 插件入口（opencode 加载点：package.json exports["./server"] → dist/server/index.js）。
 *
 * setup 序列（技术方案 §4.C1/§4.C3/§4.G）：
 * 1. 宿主版本检测（< v2.0.26 console.error 提示，不中断）；
 * 2. CLI 定位：cliJs 解析失败=安装损坏 → setup 抛结构化错误（plugin remove + add 重装指引）；
 *    解释器缺失=预期降级（MCP/siming_cli 跳过，其余照常——固定项基准 5→3）；
 * 3. 注册固定面（五样 + 任务纪律注入 + todo 三件套；降级面按解释器轴与宿主 session 域/todo 门控裁定）
 *    + reload 通道注入 + 任务创建观测；
 * 4. 初始化拉取：同步阻塞有界 10s，失败/超时空集注册不中断激活（迟到成功仍写入 store）；
 * 5. 激活自检：list() 回查固定项与动态项，区分「拉取失败（预期降级）」与「拉取成功但注册缺项」，
 *    仅激活时刻执行一次（此后动态增减由三触发点承接，正确性归 §6 刷新链单测）。
 */
import { checkHostVersion, locateCli } from '../cli-locator.js';
import { createAssetsStore } from '../assets-store.js';
import { referencesRootOf } from '../fetch-assets.js';
import { createRevalidator } from '../revalidate.js';
import { MCP_SERVER_NAME, registerMcp } from '../register/mcp.js';
import { SIMING_CLI_TOOL_NAME, registerSimingCli } from '../register/tools.js';
import { SIMING_REFRESH_TOOL_NAME, registerRefreshTool } from '../register/refresh-tool.js';
import { registerTaskDiscipline } from '../register/task-discipline.js';
import { registerSkills } from '../register/skills.js';
import { registerAgents } from '../register/agents.js';
import { registerTodoSuite } from '../register/todo-suite.js';
import { createTodoNudgeConfig } from '../todo/config.js';
import { GUIDE_SKILL_NAME } from '../guide-skill.js';
import { listEntryNames } from '../host-api.js';
/** 激活自检（§4.G：固定项按双轴基准；动态项区分拉取失败与注册缺项；异常 console.error） */
async function selfCheck(ctx, store, revalidator, opts) {
    const problems = [];
    let skillCount = 0;
    let agentCount = 0;
    try {
        const [mcpEntries, skillEntries, agentEntries, toolEntries] = await Promise.all([
            ctx.mcp.list(),
            ctx.skill.list(),
            ctx.agent.list(),
            ctx.tool.list(),
        ]);
        const mcpNames = listEntryNames(mcpEntries);
        const skillNames = listEntryNames(skillEntries);
        const agentNames = listEntryNames(agentEntries);
        const toolNames = listEntryNames(toolEntries);
        // 固定项：解释器轴成功基准 5，轴降级基准 3（MCP/siming_cli 缺=预期不告警）
        if (opts.interpreterOk && !mcpNames.has(MCP_SERVER_NAME)) {
            problems.push(`MCP "${MCP_SERVER_NAME}" 未出现在 mcp 域注册表`);
        }
        if (opts.interpreterOk && !toolNames.has(SIMING_CLI_TOOL_NAME)) {
            problems.push(`工具 ${SIMING_CLI_TOOL_NAME} 未出现在 tool 域注册表`);
        }
        // siming_refresh / 引导技能不依赖解释器发现链——缺=真缺项
        if (!toolNames.has(SIMING_REFRESH_TOOL_NAME)) {
            problems.push(`工具 ${SIMING_REFRESH_TOOL_NAME} 未出现在 tool 域注册表`);
        }
        if (!skillNames.has(GUIDE_SKILL_NAME)) {
            problems.push(`引导技能 ${GUIDE_SKILL_NAME} 未出现在 skill 域注册表`);
        }
        // 任务纪律注入（T202610160002）仅依赖宿主 session 域——缺=本宿主不注入（真缺项，非预期降级）
        if (typeof ctx.session?.hook !== 'function' || typeof ctx.session?.get !== 'function') {
            problems.push('任务纪律注入 session 域不可用（context hook 或 session.get 缺失）——本宿主不注入任务纪律提示词');
        }
        // todo 三件套（T202610260002）：active 时 task-planning 技能必须在册（系统提示词/提醒注入不走注册表）
        if (opts.todo !== null && opts.todo.status === 'active' && opts.todo.skillInfo !== null) {
            if (!skillNames.has(opts.todo.skillInfo.name)) {
                problems.push(`技能 ${opts.todo.skillInfo.name} 已内置于插件但未出现在 skill 域注册表`);
            }
        }
        // 动态项：拉取成功但注册缺项（拉取失败时 store 为空、此处自然无比对项=预期降级不告警）
        const snapshot = store.getSnapshot();
        for (const skill of snapshot.skills) {
            if (!skillNames.has(skill.name))
                problems.push(`技能 ${skill.name} 已拉取但未出现在 skill 域注册表`);
        }
        for (const agent of snapshot.agents) {
            if (!agentNames.has(agent.name))
                problems.push(`子代理 ${agent.name} 已拉取但未出现在 agent 域注册表`);
        }
        skillCount = snapshot.skills.length;
        agentCount = snapshot.agents.length;
    }
    catch (err) {
        problems.push(`注册表回查失败：${String(err)}`);
    }
    if (problems.length > 0) {
        console.error(`[siming-plugin] 激活自检发现异常（${String(problems.length)} 项，doctor 会话内可二次查证）：\n- ${problems.join('\n- ')}`);
        return;
    }
    const target = revalidator.getLastResolvedTarget();
    const bindLabel = target === null
        ? ''
        : target.projectId === null
            ? ''
            : target.projectSource === 'workspace'
                ? '，项目已绑定（工作区 defaultProject）'
                : '，项目已绑定（实例默认项目）';
    // todo 三件套状态段（T202610260002 §4.6）：active 顺带开关现值与 watcher 健康度
    let todoLabel = '';
    if (opts.todo === null) {
        todoLabel = '；todo 提醒：本宿主不支持（session 域缺失）';
    }
    else if (opts.todo.status === 'error') {
        todoLabel = `；todo 提醒：未激活（初始化异常${opts.todo.reason === undefined ? '' : `：${opts.todo.reason}`}，重启宿主后重试）`;
    }
    else if (opts.todo.status === 'gated-off') {
        todoLabel = '；todo 提醒：未激活（宿主未开启 experimental.todo，开启并重启后生效）';
    }
    else {
        const snap = opts.todoConfig.snapshot();
        todoLabel =
            snap === null
                ? '；todo 提醒：激活，配置损坏按关闭处理'
                : `；todo 提醒：${snap.enabled ? '开' : '关'}（每 ${String(snap.every)} 次）`;
        if (!opts.todoConfig.healthy())
            todoLabel += '，配置热重载不可用（变更需重启生效）';
    }
    console.log(`[siming-plugin] 激活完成：固定 ${opts.interpreterOk ? '5' : '3'} 项（解释器${opts.interpreterOk ? '正常' : '缺失降级'}）` +
        ` + 技能 ${String(skillCount)} + 子代理 ${String(agentCount)}` +
        `${target !== null ? `（server：${target.serverUrl}${bindLabel}）` : ''}` +
        `${todoLabel}` +
        `${skillCount === 0 && agentCount === 0 ? '——资产拉取未成功（空集注册，首次建任务/手动刷新时自动重试）' : ''}`);
}
const plugin = {
    id: '@siming-org/opencode-plugin',
    setup: async (ctx) => {
        checkHostVersion();
        const { nodeBin, cliJs } = locateCli();
        if (cliJs === null) {
            // 安装损坏：抛结构化错误中断激活（宿主按加载失败处理并透出，重装即恢复）
            throw new Error('[siming-plugin] 安装损坏：@siming-org/cli 依赖解析失败——' +
                '请执行 opencode plugin remove @siming-org/opencode-plugin && opencode plugin add @siming-org/opencode-plugin 重装');
        }
        // 目录基准：本 location 的 directory（v2.0.26 实测：ToolContext 无 directory 字段，
        // ctx.location.directory 于 setup 时可得——三触发与工具 cwd 统一取此值）。
        // per-location 实例（T202610220003）：store + revalidator 每次各构造一个，本 location 的
        // 拉取/注册/刷新/自检全链闭环在这对实例上——多 location 互不覆盖（历史缺陷：模块级单例被
        // 最后完成初始化的 location 覆盖，其他 location 的 project 域技能从注册表消失）。
        const directory = ctx.location.directory;
        // 附件缓存根：setup 一次求值（referencesRootOf(directory)），既供注册展示路径，又经
        // createRevalidator 传入 revalidator 贯穿会话——物化与展示始终同源（T202610220004 决策 B），
        // 不因运行期可写性翻转而换根。
        const referencesRoot = referencesRootOf(directory);
        const store = createAssetsStore();
        const revalidator = createRevalidator(store, directory, referencesRoot);
        // 注册面（解释器轴降级：MCP 与 siming_cli 跳过，其余照常；任务纪律注入不在此轴，仅依赖宿主 session 域）
        // todo 三件套（T202610260002 §4.6）：config 实例在此创建，同一实例贯穿注入判定/计数复位/selfCheck；
        // 双层兜底（suite 内部 + 此处调用位）确保 todo 任何初始化异常不阻断其余注册面（§6 契约）
        const todoNudgeConfig = createTodoNudgeConfig(directory);
        let todoSuite = await registerTodoSuite(ctx, directory, referencesRoot, todoNudgeConfig).catch((err) => {
            console.error(`[siming-plugin] ${directory}：todo 三件套注册异常（${String(err)}）——todo 不生效，其余注册面不受影响`);
            return { skillInfo: null, status: 'error', reason: String(err) };
        });
        if (nodeBin !== null)
            registerMcp(ctx, { nodeBin, cliJs });
        registerRefreshTool(ctx, revalidator, store);
        registerSkills(ctx, store, referencesRoot, todoSuite.skillInfo === null ? [] : [todoSuite.skillInfo]);
        registerAgents(ctx, store);
        if (nodeBin !== null)
            registerSimingCli(ctx, { nodeBin, cliJs }, directory);
        registerTaskDiscipline(ctx, directory);
        // 变更生效通道 + 任务创建观测（fire-and-forget）——均注入本 location 实例
        revalidator.setReloader('skill', () => ctx.skill.reload());
        revalidator.setReloader('agent', () => ctx.agent.reload());
        revalidator.observeTaskCreate(ctx.tool);
        // 初始化拉取（setup 期会话未建立 → 构造时 location directory 基准，§4.C3-3）
        await revalidator.initFetch();
        // 激活自检（仅此刻一次）
        await selfCheck(ctx, store, revalidator, {
            interpreterOk: nodeBin !== null,
            todo: todoSuite,
            todoConfig: todoNudgeConfig,
        });
    },
};
export default plugin;
//# sourceMappingURL=index.js.map
